from __future__ import annotations

from typing import Any, Dict, Mapping, Optional

import deepl


def translate_dict_values(
    data: Mapping[str, Any],
    target_lang: str,
    source_lang: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Translate all string values in a dictionary while preserving keys.

    Nested dictionaries and lists are translated recursively.
    Non-string scalar values are returned unchanged.
    """
    translator = deepl.Translator(auth_key=__import__("os").environ["DEEPL_AUTH_KEY"])

    def _translate_value(value: Any) -> Any:
        if isinstance(value, str):
            if not value:
                return value
            kwargs = {"target_lang": target_lang}
            if source_lang:
                kwargs["source_lang"] = source_lang
            result = translator.translate_text(value, **kwargs)
            return result.text
        if isinstance(value, Mapping):
            return {k: _translate_value(v) for k, v in value.items()}
        if isinstance(value, list):
            return [_translate_value(v) for v in value]
        if isinstance(value, tuple):
            return tuple(_translate_value(v) for v in value)
        return value

    return {k: _translate_value(v) for k, v in data.items()}
